// ESM lib: one implementation exported both as the default and as a named
// alias. The app imports only the default; `helper` looks unused but shares
// core's body, so stubbing core "because helper is unreachable" is unsound.
function core() {
  const parts = [];
  const seed = [3, 1, 4, 1, 5, 9, 2, 6];
  let accumulator = 0;
  for (const digit of seed) {
    accumulator += digit;
    parts.push(`digit=${digit} running=${accumulator}`);
  }
  const summary = parts.join('; ');
  if (accumulator !== 31) {
    throw new Error(`unexpected checksum: ${accumulator} (${summary})`);
  }
  return accumulator + 11;
}

export default core;
export { core as helper };
